  // Contrôleur rôles Discord et permissions
  let discordRolesData = [];
  let staffRolesData = [];
  let discordGuildId = '';
  let discordCanManage = false;
  let discordCurrentFilter = 'all';
  let discordSearchQuery = '';
  let isSavingDiscord = false;
  let isSyncingDiscord = false;
  let discordShowSecondaryOnCards = true;

  let permRoleDefs = [];
  let permissionDefinitions = {};
  let rolePermissionsMatrix = {};
  let isSavingPerms = false;
  let permSearchQuery = '';

  function normalizeRoleStr(r) {
    return String(r || '').toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g, '').trim();
  }

  function canManagePermissions(user) {
    if (!user) return false;
    if (user.is_master_ceo || user.site_role === 'admin') return true;
    const r = normalizeRoleStr(user.staff_role);
    if (['createur', 'ceo', 'co_ceo', 'developer', 'developpeur', 'equipe technique', 'equipe_technique'].includes(r)) return true;
    if (user.permissions && user.permissions.manage_permissions) return true;
    if (window.SDAuth && typeof window.SDAuth.sdHasPermission === 'function') {
      return !!window.SDAuth.sdHasPermission(user, 'manage_permissions');
    }
    return false;
  }

  function renderTopTabs(activeTab) {
    return `
      <div class="sd-cand-tabs" style="margin-bottom:1.15rem;">
        <button type="button" class="sd-cand-tabs__btn ${activeTab === 'discord-roles' ? 'is-active' : ''}" data-switch-tab="discord-roles">
          🎭 Rôles Discord & Hiérarchie
        </button>
        <button type="button" class="sd-cand-tabs__btn ${activeTab === 'role-permissions' ? 'is-active' : ''}" data-switch-tab="role-permissions">
          🛡️ Permissions par Rôle
        </button>
      </div>
    `;
  }

  async function loadAndRenderDiscordView(container) {
    container.innerHTML = `
      <div class="sd-admin-panel" style="animation: fadeIn .2s ease;">
        <div class="sd-admin-loading" style="padding: 4rem 1rem;">
          <div class="sd-admin-loading__spinner"></div>
          <p style="margin-top:1rem;color:#ffffffa6;">Interrogation de Discord en temps réel...</p>
        </div>
      </div>
    `;

    try {
      const res = await window.SDAuth.sdApi('/roles/discord-mapping.php');
      if (!res.success) throw new Error(res.error || 'Erreur lors du chargement des rôles Discord.');

      discordRolesData = (res.discord_roles || []).map(r => { if (r && r.name) { r.name = cleanDiscordRoleName(r.name); } return r; });
      staffRolesData = res.staff_roles || [];
      discordGuildId = res.guild_id || '';
      discordCanManage = !!res.can_manage;
      discordShowSecondaryOnCards = res.show_secondary_roles !== false;

      renderDiscordInterface(container);
    } catch (err) {
      container.innerHTML = `
        <div class="sd-admin-panel">
          <div class="sd-admin-panel__head"><h1>Rôles Discord</h1></div>
          <div class="sd-admin-panel__body">
            <div class="sd-admin-alert" style="border-color:#ff646459;background:#ff64641a;">
              <strong style="color:#ff8e8e;">Échec du chargement des rôles Discord</strong>
              <p>${C(err.message || 'Impossible de contacter l\'API Discord.')}</p>
            </div>
            <button type="button" class="sd-admin-panel__btn" id="sd-dr-retry" style="width:fit-content;">Réessayer</button>
          </div>
        </div>
      `;
      container.querySelector('#sd-dr-retry')?.addEventListener('click', () => loadAndRenderDiscordView(container));
    }
  }

  function renderDiscordInterface(container) {
    const totalRoles = discordRolesData.length;
    const activeRolesList = discordRolesData.filter(r => !!r.auto_assign);
    const activeRolesCount = activeRolesList.length;
    const inactiveRolesCount = totalRoles - activeRolesCount;

    // Calcul de la position hiérarchique parmi les rôles actifs
    const activeRankMap = new Map();
    activeRolesList.forEach((r, idx) => {
      activeRankMap.set(r.id, idx + 1);
    });

    const filtered = discordRolesData.filter(r => {
      if (discordCurrentFilter === 'active' && !r.auto_assign) return false;
      if (discordCurrentFilter === 'inactive' && r.auto_assign) return false;
      if (discordSearchQuery) {
        const q = discordSearchQuery.toLowerCase();
        const name = String(r.name || '').toLowerCase();
        const id = String(r.id || '');
        return name.includes(q) || id.includes(q);
      }
      return true;
    });

    container.innerHTML = `
      <div class="sd-admin-panel" style="animation: fadeIn .15s ease;">
        <div class="sd-admin-panel__head" style="gap: 1rem; align-items: flex-start;">
          <div class="sd-admin-panel__head-main" style="max-width: 40rem;">
            ${renderTopTabs('discord-roles')}
            <h1 style="margin:0;display:flex;align-items:center;gap:10px;">
              <span style="display:inline-block;padding:3px 7px;border-radius:6px;background:rgba(88,101,242,.2);border:1px solid rgba(88,101,242,.4);color:#5865F2;font-size:.7em;letter-spacing:.08em;">DISCORD</span>
              Rôles Discord & Hiérarchie Staff
            </h1>
            <p class="sd-admin-panel__sub" style="margin-top:6px;line-height:1.45;">
              Activez directement les rôles Discord souhaités pour votre équipe et organisez leur ordre de supériorité avec les flèches <strong>⬆️</strong> et <strong>⬇️</strong>. Le rôle <strong>#1</strong> est le plus haut dans la hiérarchie.
            </p>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:.6rem;align-items:center;margin-left:auto;">
            <button type="button" class="sd-admin-panel__btn sd-admin-panel__btn--ghost" id="sd-dr-refresh" title="Recharger les rôles Discord">
              🔄 Actualiser
            </button>
            <button type="button" class="sd-admin-panel__btn sd-admin-panel__btn--ghost" id="sd-dr-sync" ${isSyncingDiscord ? 'disabled' : ''} style="border-color:rgba(88,101,242,.4);color:#5865F2;">
              ⚡ ${isSyncingDiscord ? 'Synchronisation...' : 'Synchroniser tout'}
            </button>
            <button type="button" class="sd-admin-panel__btn" id="sd-dr-save" ${isSavingDiscord ? 'disabled' : ''} style="background:var(--sd-neon, #1ee6a0);color:#071612;font-weight:800;">
              ${isSavingDiscord ? 'Enregistrement...' : '💾 Enregistrer'}
            </button>
          </div>
        </div>

        <div class="sd-admin-panel__body" style="gap: 1.25rem;">
          <div class="sd-settings-block--framed" style="display:flex;align-items:center;justify-content:space-between;gap:1.2rem;padding:1.05rem 1.35rem;border-radius:12px;background:linear-gradient(160deg, rgba(88,101,242,.09), rgba(0,0,0,.45));border:1px solid rgba(88,101,242,.28);margin-bottom:.35rem;">
            <div style="display:flex;align-items:center;gap:14px;">
              <span style="font-size:1.6rem;line-height:1;">🪪</span>
              <div>
                <strong style="color:#fff;font-size:.92rem;display:flex;align-items:center;gap:8px;">
                  Affichage des rôles secondaires sur la carte (Page Équipe)
                </strong>
                <p style="margin:3px 0 0;font-size:.78rem;color:#ffffff99;line-height:1.4;">
                  Affiche tous les badges des grades secondaires sous le nom des membres sur leurs cartes de l'équipe staff (en plus de leur rôle principal).
                </p>
              </div>
            </div>
            <label class="sd-settings-toggle" style="margin:0;cursor:pointer;flex-shrink:0;" title="Activer ou désactiver l'affichage des rôles secondaires sur les cartes staff">
              <input type="checkbox" id="sd-dr-toggle-secondary-cards" ${discordShowSecondaryOnCards ? 'checked' : ''} />
              <span class="sd-settings-toggle__track"></span>
            </label>
          </div>

          <div style="display:flex;flex-wrap:wrap;gap:.75rem;align-items:center;justify-content:space-between;">
            <div class="sd-cand-tabs" style="margin:0;">
              <button type="button" class="sd-cand-tabs__btn ${discordCurrentFilter === 'all' ? 'is-active' : ''}" data-filter="all">
                Tous (${totalRoles})
              </button>
              <button type="button" class="sd-cand-tabs__btn ${discordCurrentFilter === 'active' ? 'is-active' : ''}" data-filter="active">
                Staff Actif (${activeRolesCount})
              </button>
              <button type="button" class="sd-cand-tabs__btn ${discordCurrentFilter === 'inactive' ? 'is-active' : ''}" data-filter="inactive">
                Non Staff (${inactiveRolesCount})
              </button>
            </div>
            <div style="min-width:16rem;flex:1;max-width:24rem;">
              <input 
                type="search" 
                id="sd-dr-search" 
                class="sd-admin__search" 
                placeholder="🔍 Filtrer les rôles Discord..." 
                value="${C(discordSearchQuery)}"
                style="width:100%;padding:.55rem .85rem;font-size:.82rem;background:#05050580;"
              />
            </div>
          </div>

          <div class="sd-admin-table-wrap" style="overflow-x:auto;border-radius:10px;border:1px solid rgba(255,255,255,.08);background:#07070788;">
            <table class="sd-admin-table" style="width:100%;border-collapse:collapse;min-width:720px;">
              <thead>
                <tr style="background:#ffffff06;text-align:left;border-bottom:1px solid rgba(255,255,255,.08);">
                  <th style="padding:.75rem 1rem;font-size:.75rem;text-transform:uppercase;color:#ffffff73;width:36%;">Rôle Discord</th>
                  <th style="padding:.75rem 1rem;font-size:.75rem;text-transform:uppercase;color:#ffffff73;width:24%;text-align:center;">Hiérarchie / Ordre</th>
                  <th style="padding:.75rem 1rem;font-size:.75rem;text-transform:uppercase;color:#ffffff73;width:18%;text-align:center;">Rôle Staff</th>
                  <th style="padding:.75rem 1rem;font-size:.75rem;text-transform:uppercase;color:#ffffff73;width:22%;">Aperçu Badge</th>
                </tr>
              </thead>
              <tbody id="sd-dr-table-body">
                ${filtered.length === 0 ? `<tr><td colspan="4" style="text-align:center;padding:2.5rem;color:#ffffff61;">Aucun rôle Discord ne correspond aux critères.</td></tr>` : filtered.map(r => renderDiscordRoleRow(r, activeRankMap.get(r.id), activeRolesCount)).join('')}
              </tbody>
            </table>
          </div>

          <div class="sd-admin-alert" style="margin-top:.5rem;">
            <strong>💡 Fonctionnement de la hiérarchie Discord directe</strong>
            <p>
              • <strong>Ordre & Supériorité</strong> : Utilisez les boutons <strong>⬆️ Monter</strong> et <strong>⬇️ Descendre</strong> sur les rôles staff actifs. Le rôle <strong>#1</strong> possède la priorité maximale (rôle principal pour les membres multi-rôles et en tête sur la page Équipe).<br>
              • <strong>Rôle Staff</strong> : Cochez <strong>OUI</strong> pour inclure le rôle dans l'équipe du site. Dès qu'un membre possède ce rôle sur Discord, ses accès staff sont accordés en temps réel.<br>
              • N'oubliez pas de cliquer sur <strong>💾 Enregistrer</strong> en haut à droite après avoir réorganisé vos rôles.
            </p>
          </div>
        </div>
      </div>
    `;

    bindDiscordEvents(container);
  }

  function cleanDiscordRoleName(name) {
    if (!name) return '';
    try {
      return String(name).replace(/^[\s»›>«‹▶►▸•·|―\-–—]+|[\s»›>«‹▶►▸•·|―\-–—]+$/gu, '').trim() || name;
    } catch (e) {
      return name;
    }
  }
  function renderDiscordRoleRow(role, activeRank, totalActive) {
    const isStaff = !!role.auto_assign;
    const colorStyle = role.color && role.color !== '#000000' ? role.color : '#99aab5';
    const isEveryone = !!role.is_everyone;

    let orderControlsHtml = `<span style="font-size:.78rem;color:#ffffff38;">—</span>`;
    if (isStaff && activeRank) {
      const canMoveUp = activeRank > 1;
      const canMoveDown = activeRank < totalActive;
      orderControlsHtml = `
        <div style="display:inline-flex;align-items:center;justify-content:center;gap:6px;">
          <span style="display:inline-block;padding:3px 8px;border-radius:6px;background:rgba(88,101,242,.15);border:1px solid rgba(88,101,242,.35);font-family:monospace;font-size:.78rem;font-weight:800;color:#fff;min-width:32px;text-align:center;">
            #${activeRank}
          </span>
          <button type="button" class="sd-dr-move-btn" data-dr-move="up" data-role-id="${role.id}" ${canMoveUp ? '' : 'disabled'} title="Monter (Rang supérieur)" style="width:28px;height:28px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:6px;background:${canMoveUp ? 'rgba(255,255,255,.08)' : 'transparent'};border:1px solid ${canMoveUp ? 'rgba(255,255,255,.2)' : 'rgba(255,255,255,.05)'};color:${canMoveUp ? '#fff' : '#ffffff25'};cursor:${canMoveUp ? 'pointer' : 'not-allowed'};font-size:.8rem;line-height:1;transition:all .15s ease;">
            ▲
          </button>
          <button type="button" class="sd-dr-move-btn" data-dr-move="down" data-role-id="${role.id}" ${canMoveDown ? '' : 'disabled'} title="Descendre (Rang inférieur)" style="width:28px;height:28px;padding:0;display:inline-flex;align-items:center;justify-content:center;border-radius:6px;background:${canMoveDown ? 'rgba(255,255,255,.08)' : 'transparent'};border:1px solid ${canMoveDown ? 'rgba(255,255,255,.2)' : 'rgba(255,255,255,.05)'};color:${canMoveDown ? '#fff' : '#ffffff25'};cursor:${canMoveDown ? 'pointer' : 'not-allowed'};font-size:.8rem;line-height:1;transition:all .15s ease;">
            ▼
          </button>
        </div>
      `;
    }

    return `
      <tr data-role-id="${role.id}" style="${!isStaff ? 'opacity:.68;' : ''}">
        <td>
          <div style="display:flex;align-items:center;gap:10px;">
            <span style="display:inline-block;width:14px;height:14px;border-radius:50%;background:${colorStyle};box-shadow:0 0 8px ${colorStyle}88;flex-shrink:0;"></span>
            <div style="min-width:0;">
              <div style="display:flex;align-items:center;gap:8px;">
                <strong style="color:#fff;font-size:.92rem;">${C(cleanDiscordRoleName(role.name))}</strong>
                ${role.managed ? '<span class="sd-staff-chip sd-staff-chip--muted" style="font-size:.58rem;padding:.1rem .35rem;">BOT</span>' : ''}
                ${isEveryone ? '<span class="sd-staff-chip sd-staff-chip--muted" style="font-size:.58rem;padding:.1rem .35rem;">EVERYONE</span>' : ''}
              </div>
              <div style="font-family:monospace;font-size:.7rem;color:#ffffff61;margin-top:2px;">
                ID: ${role.id} · Discord Pos: ${role.position}
              </div>
            </div>
          </div>
        </td>

        <td style="text-align:center;">
          ${orderControlsHtml}
        </td>

        <td style="text-align:center;">
          <div style="display:inline-flex;align-items:center;justify-content:center;gap:8px;">
            <label class="sd-settings-toggle" style="margin:0;cursor:pointer;">
              <input type="checkbox" class="sd-dr-toggle" data-role-id="${role.id}" ${isStaff ? 'checked' : ''} />
              <span class="sd-settings-toggle__track"></span>
            </label>
            <span class="sd-dr-status-label" style="font-size:.76rem;font-weight:700;letter-spacing:.04em;color:${isStaff ? 'var(--sd-neon, #1ee6a0)' : '#ffffff59'};min-width:38px;text-align:left;">
              ${isStaff ? 'OUI' : 'NON'}
            </span>
          </div>
        </td>

        <td class="sd-dr-badge-cell">
          ${isStaff ? `
            <span class="sd-staff-chip" style="border-color:${colorStyle}55;background:${colorStyle}18;color:${colorStyle};font-weight:700;letter-spacing:.04em;text-transform:uppercase;">
              ${C(cleanDiscordRoleName(role.name))}
            </span>
          ` : '<span class="sd-staff-chip sd-staff-chip--muted" style="color:#ffffff59;">Non staff</span>'}
        </td>
      </tr>
    `;
  }

  function bindDiscordEvents(container) {
    container.querySelectorAll('[data-switch-tab]').forEach(btn => {
      btn.addEventListener('click', () => {
        const tab = btn.dataset.switchTab;
        F(tab);
      });
    });

    container.querySelector('#sd-dr-refresh')?.addEventListener('click', () => loadAndRenderDiscordView(container));
    container.querySelector('#sd-dr-save')?.addEventListener('click', () => saveDiscordConfiguration(false));
    container.querySelector('#sd-dr-sync')?.addEventListener('click', () => {
      if (confirm('Voulez-vous enregistrer la configuration et lancer la synchronisation complète de tous les membres du serveur Discord dès maintenant ?')) {
        saveDiscordConfiguration(true);
      }
    });

    container.querySelectorAll('[data-filter]').forEach(btn => {
      btn.addEventListener('click', () => {
        discordCurrentFilter = btn.dataset.filter;
        renderDiscordInterface(container);
      });
    });

    const searchInput = container.querySelector('#sd-dr-search');
    if (searchInput) {
      let timeout = null;
      searchInput.addEventListener('input', e => {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          discordSearchQuery = e.target.value.trim();
          renderDiscordInterface(container);
        }, 180);
      });
    }

    const toggleSec = container.querySelector('#sd-dr-toggle-secondary-cards');
    if (toggleSec) {
      toggleSec.addEventListener('change', async (e) => {
        discordShowSecondaryOnCards = e.target.checked;
        try {
          const mappingsPayload = {};
          discordRolesData.forEach(r => {
            mappingsPayload[r.id] = {
              name: r.name || '',
              color: r.color || '',
              auto_assign: !!r.auto_assign,
              order_rank: Number(r.order_rank) || 0,
              target_role: r.target_role || ''
            };
          });
          await window.SDAuth.sdApi('/roles/discord-mapping.php', {
            method: 'POST',
            body: JSON.stringify({
              mapping: mappingsPayload,
              show_secondary_roles: discordShowSecondaryOnCards
            })
          });
          b(discordShowSecondaryOnCards ? 'Rôles secondaires activés sur les cartes !' : 'Rôles secondaires masqués sur les cartes.', 'success');
        } catch (err) {
          b(err.message || 'Erreur lors de la mise à jour.', 'error');
        }
      });
    }

    // Gestion du déplacement haut / bas dans la hiérarchie
    container.querySelectorAll('.sd-dr-move-btn').forEach(btn => {
      btn.addEventListener('click', (e) => {
        e.stopPropagation();
        const roleId = btn.dataset.roleId;
        const dir = btn.dataset.drMove;
        if (!roleId || !dir) return;

        const activeRoles = discordRolesData.filter(r => !!r.auto_assign);
        const idx = activeRoles.findIndex(r => r.id === roleId);
        if (idx === -1) return;

        if (dir === 'up' && idx > 0) {
          const temp = activeRoles[idx];
          activeRoles[idx] = activeRoles[idx - 1];
          activeRoles[idx - 1] = temp;
        } else if (dir === 'down' && idx < activeRoles.length - 1) {
          const temp = activeRoles[idx];
          activeRoles[idx] = activeRoles[idx + 1];
          activeRoles[idx + 1] = temp;
        } else {
          return;
        }

        const total = activeRoles.length;
        activeRoles.forEach((r, i) => {
          r.order_rank = (total - i) * 10;
        });

        const inactiveRoles = discordRolesData.filter(r => !r.auto_assign);
        discordRolesData = [...activeRoles, ...inactiveRoles];

        renderDiscordInterface(container);
        b('Ordre mis à jour ! Cliquez sur « Enregistrer » pour sauvegarder.', 'info');
      });
    });

    // Toggle Actif Staff (OUI / NON)
    container.querySelectorAll('.sd-dr-toggle').forEach(chk => {
      chk.addEventListener('click', e => e.stopPropagation());
      chk.addEventListener('change', e => {
        e.stopPropagation();
        const roleId = e.target.dataset.roleId;
        const role = discordRolesData.find(r => r.id === roleId);
        if (role) {
          role.auto_assign = e.target.checked;
          const activeRoles = discordRolesData.filter(r => !!r.auto_assign);
          const total = activeRoles.length;

          if (role.auto_assign) {
            role.order_rank = 10;
          } else {
            role.order_rank = 0;
          }

          activeRoles.forEach((r, i) => {
            r.order_rank = (total - i) * 10;
          });

          const inactiveRoles = discordRolesData.filter(r => !r.auto_assign);
          discordRolesData = [...activeRoles, ...inactiveRoles];

          renderDiscordInterface(container);
          b(role.auto_assign ? `« ${cleanDiscordRoleName(role.name)} » ajouté au staff !` : `« ${cleanDiscordRoleName(role.name)} » retiré du staff.`, 'info');
        }
      });
    });
  }

  async function saveDiscordConfiguration(syncNow = false) {
    if (isSavingDiscord || isSyncingDiscord) return;

    const saveBtn = document.getElementById('sd-dr-save');
    const syncBtn = document.getElementById('sd-dr-sync');

    if (syncNow) {
      isSyncingDiscord = true;
      if (syncBtn) { syncBtn.disabled = true; syncBtn.textContent = '⚡ Synchronisation...'; }
    } else {
      isSavingDiscord = true;
      if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Enregistrement...'; }
    }

    try {
      const mappingsPayload = {};
      discordRolesData.forEach(r => {
        mappingsPayload[r.id] = {
          name: r.name || '',
          color: r.color || '',
          auto_assign: !!r.auto_assign,
          order_rank: Number(r.order_rank) || 0,
          target_role: r.target_role || ''
        };
      });

      const res = await window.SDAuth.sdApi('/roles/discord-mapping.php', {
        method: 'POST',
        body: JSON.stringify({
          mapping: mappingsPayload,
          show_secondary_roles: discordShowSecondaryOnCards,
          sync_now: !!syncNow
        })
      });

      if (!res.success) throw new Error(res.error || 'Erreur lors de la sauvegarde.');

      if (syncNow && res.sync_result) {
        b(`Synchro réussie ! ${res.sync_result.synced_members || 0} membres mis à jour.`, 'success');
      } else {
        b('Configuration des rôles Discord enregistrée avec succès !', 'success');
      }
    } catch (err) {
      b(err.message || 'Erreur lors de l\'opération.', 'error');
    } finally {
      isSavingDiscord = false;
      isSyncingDiscord = false;
      if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = '💾 Enregistrer'; }
      if (syncBtn) { syncBtn.disabled = false; syncBtn.textContent = '⚡ Synchroniser tout'; }
    }
  }

  async function loadAndRenderPermsView(container) {
    container.innerHTML = `
      <div class="sd-admin-panel" style="animation: fadeIn .2s ease;">
        <div class="sd-admin-loading" style="padding: 4rem 1rem;">
          <div class="sd-admin-loading__spinner"></div>
          <p style="margin-top:1rem;color:#ffffffa6;">Chargement des permissions par rôle...</p>
        </div>
      </div>
    `;

    try {
      const res = await window.SDAuth.sdApi('/roles/permissions.php');
      if (!res.success) throw new Error(res.error || 'Erreur inconnue lors du chargement.');

      permRoleDefs = res.staff_roles || [];
      permissionDefinitions = res.permission_definitions || {};
      rolePermissionsMatrix = res.role_permissions || {};

      renderPermsInterface(container);
    } catch (err) {
      container.innerHTML = `
        <div class="sd-admin-panel">
          <div class="sd-admin-panel__head"><h1>Permissions par Rôle</h1></div>
          <div class="sd-admin-panel__body">
            <div class="sd-admin-alert" style="border-color:#ff646459;background:#ff64641a;">
              <strong style="color:#ff8e8e;">Échec du chargement des permissions</strong>
              <p>${C(err.message || 'Impossible de contacter l\'API des permissions.')}</p>
            </div>
            <button type="button" class="sd-admin-panel__btn" id="sd-perm-retry" style="width:fit-content;">Réessayer</button>
          </div>
        </div>
      `;
      container.querySelector('#sd-perm-retry')?.addEventListener('click', () => loadAndRenderPermsView(container));
    }
  }

  function renderPermsInterface(container) {
    const permKeys = Object.keys(permissionDefinitions || {});
    const filteredStaffRoles = (permRoleDefs || []).filter(role => {
      if (!role) return false;
      if (permSearchQuery) {
        const q = permSearchQuery.toLowerCase();
        const lbl = String(role.label || '').toLowerCase();
        const key = String(role.key || '').toLowerCase();
        return lbl.includes(q) || key.includes(q);
      }
      return true;
    });

    container.innerHTML = `
      <div class="sd-admin-panel" style="animation: fadeIn .15s ease;">
        <div class="sd-admin-panel__head" style="gap: 1rem; align-items: flex-start;">
          <div class="sd-admin-panel__head-main" style="max-width: 38rem;">
            ${renderTopTabs('role-permissions')}
            <h1 style="margin:0;display:flex;align-items:center;gap:10px;">
              <span style="display:inline-block;padding:3px 7px;border-radius:6px;background:rgba(30,230,160,.18);border:1px solid rgba(30,230,160,.4);color:var(--sd-neon, #1ee6a0);font-size:.7em;letter-spacing:.08em;">STAFF</span>
              Permissions par Rôle
            </h1>
            <p class="sd-admin-panel__sub" style="margin-top:6px;line-height:1.45;">
              Définissez les droits d'accès pour chaque grade staff. Les membres recevant un grade (via Discord ou manuellement) héritent automatiquement de ses permissions.
            </p>
          </div>
          <div style="display:flex;flex-wrap:wrap;gap:.6rem;align-items:center;margin-left:auto;">
            <button type="button" class="sd-admin-panel__btn sd-admin-panel__btn--ghost" id="sd-perm-refresh" title="Recharger les permissions">
              🔄 Actualiser
            </button>
            <button type="button" class="sd-admin-panel__btn" id="sd-perm-save" ${isSavingPerms ? 'disabled' : ''} style="background:var(--sd-neon, #1ee6a0);color:#071612;font-weight:800;">
              ${isSavingPerms ? 'Enregistrement...' : '💾 Enregistrer les permissions'}
            </button>
          </div>
        </div>

        <div class="sd-admin-panel__body" style="gap: 1.25rem;">
          <div style="position:relative;width:100%;">
            <input 
              type="search" 
              id="sd-perm-search" 
              class="sd-admin__search" 
              placeholder="🔍 Rechercher un rôle staff (ex: Modérateur, Administrateur, Gérant...)" 
              value="${C(permSearchQuery)}"
              style="width:100%;max-width:none;padding:.7rem 1rem;font-size:.85rem;background:#05050580;"
            />
          </div>

          <div style="display:grid;gap:1.15rem;">
            ${filteredStaffRoles.length === 0 ? '<div class="sd-admin-empty" style="padding:2.5rem;text-align:center;color:#ffffff73;">Aucun rôle staff trouvé.</div>' : filteredStaffRoles.map(role => renderRolePermCard(role, permKeys)).join('')}
          </div>

          <div class="sd-admin-alert" style="margin-top:.5rem;">
            <strong>ℹ️ À savoir sur l'héritage des permissions :</strong>
            <p>
              • Les rôles de direction (<strong>Créateur, CEO, Co-CEO</strong>) possèdent toutes les permissions activées en permanence pour garantir la pérennité de l'administration.<br>
              • Si un membre cumule plusieurs rôles (rôle principal + rôles secondaires), il bénéficie du <strong>cumul de toutes les permissions</strong> accordées par ses différents grades.
            </p>
          </div>
        </div>
      </div>
    `;

    bindPermsEvents(container);
  }

  function renderRolePermCard(role, permKeys) {
    if (!role) return '';
    const normKey = normalizeRoleStr(role.key);
    const isProtected = ['createur', 'ceo', 'co_ceo', 'developer', 'developpeur', 'equipe technique', 'equipe_technique'].includes(normKey);
    const rolePerms = (rolePermissionsMatrix && rolePermissionsMatrix[role.key]) || {};
    const rankLabel = role.rank ? `Rang ${role.rank}` : '';

    return `
      <div class="sd-settings-block--framed" style="padding:1.1rem 1.25rem;border-radius:12px;background:linear-gradient(160deg, rgba(255,255,255,.03), rgba(0,0,0,.45));border:1px solid rgba(255,255,255,.09);" data-role-card="${C(role.key)}">
        <div style="display:flex;flex-wrap:wrap;align-items:center;justify-content:space-between;gap:.75rem;padding-bottom:.85rem;margin-bottom:1rem;border-bottom:1px solid rgba(255,255,255,.07);">
          <div style="display:flex;align-items:center;gap:10px;">
            <strong style="font-size:1.1rem;color:#fff;letter-spacing:-.01em;">${C(role.label || role.key)}</strong>
            <span class="sd-staff-chip sd-staff-chip--outline" style="font-family:monospace;font-size:.65rem;color:#ffffff99;">
              ${C(role.key)}
            </span>
            ${rankLabel ? `<span class="sd-staff-chip sd-staff-chip--muted" style="font-size:.62rem;">${C(rankLabel)}</span>` : ''}
          </div>

          <div>
            ${isProtected ? `
              <span class="sd-staff-chip sd-staff-chip--ok" style="font-size:.68rem;padding:.25rem .6rem;">
                🔒 Direction & Technique (Toutes permissions actives)
              </span>
            ` : `
              <div style="display:inline-flex;gap:.4rem;">
                <button type="button" class="sd-cand-toolbar__btn sd-perm-all-btn" data-role="${role.key}" style="font-size:.64rem;padding:.25rem .55rem;">
                  Tout activer
                </button>
                <button type="button" class="sd-cand-toolbar__btn sd-perm-none-btn" data-role="${role.key}" style="font-size:.64rem;padding:.25rem .55rem;">
                  Tout désactiver
                </button>
              </div>
            `}
          </div>
        </div>

        <div style="display:grid;grid-template-columns:repeat(auto-fit, minmax(280px, 1fr));gap:.75rem;">
          ${permKeys.map(permKey => {
            const def = permissionDefinitions[permKey] || { label: permKey, description: '', icon: '🔑' };
            const isChecked = isProtected || !!rolePerms[permKey];
            const disabled = isProtected ? 'disabled' : '';

            return `
              <div class="sd-perm-item-box" style="display:flex;align-items:flex-start;gap:.75rem;padding:.75rem .85rem;border-radius:8px;background:rgba(0,0,0,.35);border:1px solid ${isChecked ? 'rgba(30,230,160,.25)' : 'rgba(255,255,255,.05)'};transition:border-color .15s;">
                <span style="font-size:1.25rem;line-height:1;margin-top:2px;">${def.icon}</span>
                <div style="flex:1;min-width:0;">
                  <div style="display:flex;align-items:center;justify-content:space-between;gap:6px;margin-bottom:2px;">
                    <span style="font-size:.82rem;font-weight:700;color:${isChecked ? '#fff' : '#ffffffa6'};">
                      ${C(def.label)}
                    </span>
                    <label class="sd-settings-toggle" style="margin:0;cursor:${isProtected ? 'default' : 'pointer'};">
                      <input 
                        type="checkbox" 
                        class="sd-perm-toggle-input" 
                        data-role="${role.key}" 
                        data-perm="${permKey}" 
                        ${isChecked ? 'checked' : ''} 
                        ${disabled} 
                      />
                      <span class="sd-settings-toggle__track" style="${isProtected ? 'opacity:.75;' : ''}"></span>
                    </label>
                  </div>
                  <p style="margin:0;font-size:.72rem;color:#ffffff73;line-height:1.35;">
                    ${C(def.description)}
                  </p>
                </div>
              </div>
            `;
          }).join('')}
        </div>
      </div>
    `;
  }

  function bindPermsEvents(container) {
    container.querySelectorAll('[data-switch-tab]').forEach(btn => {
      btn.addEventListener('click', () => {
        const tab = btn.dataset.switchTab;
        F(tab);
      });
    });

    container.querySelector('#sd-perm-refresh')?.addEventListener('click', () => loadAndRenderPermsView(container));
    container.querySelector('#sd-perm-save')?.addEventListener('click', () => saveRolePermissions());

    const searchInput = container.querySelector('#sd-perm-search');
    if (searchInput) {
      let timeout = null;
      searchInput.addEventListener('input', e => {
        clearTimeout(timeout);
        timeout = setTimeout(() => {
          permSearchQuery = e.target.value.trim();
          renderPermsInterface(container);
        }, 180);
      });
    }

    // Tout activer
    container.querySelectorAll('.sd-perm-all-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        const rKey = btn.dataset.role;
        if (!rolePermissionsMatrix[rKey]) rolePermissionsMatrix[rKey] = {};
        Object.keys(permissionDefinitions).forEach(pk => {
          rolePermissionsMatrix[rKey][pk] = true;
        });

        const card = btn.closest('[data-role-card]');
        if (card) {
          card.querySelectorAll('.sd-perm-toggle-input').forEach(chk => {
            chk.checked = true;
            const box = chk.closest('.sd-perm-item-box');
            if (box) box.style.borderColor = 'rgba(30,230,160,.25)';
          });
        }
      });
    });

    // Tout désactiver
    container.querySelectorAll('.sd-perm-none-btn').forEach(btn => {
      btn.addEventListener('click', e => {
        e.preventDefault();
        e.stopPropagation();
        const rKey = btn.dataset.role;
        if (!rolePermissionsMatrix[rKey]) rolePermissionsMatrix[rKey] = {};
        Object.keys(permissionDefinitions).forEach(pk => {
          rolePermissionsMatrix[rKey][pk] = false;
        });

        const card = btn.closest('[data-role-card]');
        if (card) {
          card.querySelectorAll('.sd-perm-toggle-input').forEach(chk => {
            chk.checked = false;
            const box = chk.closest('.sd-perm-item-box');
            if (box) box.style.borderColor = 'rgba(255,255,255,.05)';
          });
        }
      });
    });

    // Toggle individuel
    container.querySelectorAll('.sd-perm-toggle-input').forEach(chk => {
      chk.addEventListener('click', e => e.stopPropagation());
      chk.addEventListener('change', e => {
        e.stopPropagation();
        const rKey = e.target.dataset.role;
        const pKey = e.target.dataset.perm;
        if (!rolePermissionsMatrix[rKey]) rolePermissionsMatrix[rKey] = {};
        rolePermissionsMatrix[rKey][pKey] = e.target.checked;

        const box = e.target.closest('.sd-perm-item-box');
        if (box) {
          box.style.borderColor = e.target.checked ? 'rgba(30,230,160,.25)' : 'rgba(255,255,255,.05)';
        }
      });
    });
  }

  async function saveRolePermissions() {
    if (isSavingPerms) return;
    const saveBtn = document.getElementById('sd-perm-save');
    isSavingPerms = true;
    if (saveBtn) { saveBtn.disabled = true; saveBtn.textContent = 'Enregistrement...'; }

    try {
      const res = await window.SDAuth.sdApi('/roles/permissions.php', {
        method: 'POST',
        body: JSON.stringify({
          permissions: rolePermissionsMatrix
        })
      });

      if (!res.success) throw new Error(res.error || 'Erreur lors de la sauvegarde des permissions.');

      b('Permissions des rôles staff enregistrées avec succès !', 'success');
    } catch (err) {
      b(err.message || 'Erreur lors de la sauvegarde.', 'error');
    } finally {
      isSavingPerms = false;
      if (saveBtn) { saveBtn.disabled = false; saveBtn.textContent = '💾 Enregistrer les permissions'; }
    }
  }

